<template>
  <div class="knowledge-view">
    <header class="hero"><div><span>EVIDENCE KNOWLEDGE</span><h1>知识与证据中心</h1><p>真实混合检索连接原始文档、抽取字段和知识图谱。</p></div><button @click="creating=!creating">＋ 新建知识库</button></header>
    <section v-if="creating" class="create-bar"><input v-model.trim="form.name" placeholder="知识库名称"><input v-model.trim="form.description" placeholder="用途说明"><select v-model="form.retrieval_mode"><option value="hybrid">混合检索</option><option value="keyword">关键词检索</option><option value="vector">向量检索</option></select><button @click="create">创建</button></section>
    <section class="workspace">
      <aside><div class="aside-head"><b>知识库</b><small>{{ collections.length }}</small></div><button v-for="item in collections" :key="item.id" :class="{active:item.id===selectedId}" @click="choose(item.id)"><span><b>{{ item.name }}</b><small>{{ item.documents }} 份文档 · {{ modeNames[item.retrieval_mode] }}</small></span><em>›</em></button><p v-if="!collections.length" class="empty">先创建一个知识库</p></aside>
      <main v-if="selected">
        <div class="library-head"><div><h2>{{ selected.name }}</h2><p>{{ selected.description || '用于组织材料并提供可追溯检索。' }}</p></div><div class="add-doc"><select v-model="documentId"><option value="">选择工作台文档</option><option v-for="doc in availableDocuments" :key="doc.id" :value="doc.id">{{ doc.filename }}</option></select><button :disabled="!documentId" @click="addDocument">加入知识库</button></div></div>
        <div class="library-meta"><span v-for="doc in indexedDocuments" :key="doc.id">{{ doc.filename }}<small>{{ doc.chunk_count }} 段</small></span><i v-if="!indexedDocuments.length">暂未加入文档</i></div>
        <div class="view-tabs"><button :class="{active:view==='search'}" @click="view='search'">混合检索</button><button :class="{active:view==='graph'}" @click="showGraph">知识图谱</button></div>
        <section v-if="view==='search'" class="search-view"><div class="search-box"><input v-model.trim="query" placeholder="输入问题或关键词，例如：项目负责人和预算是多少？" @keyup.enter="search"><button :disabled="query.length<2" @click="search">检索</button></div><div class="search-note">结果由关键词相关度与本地向量余弦相似度共同排序，并返回来源位置。</div><article v-for="(item,index) in results" :key="item.chunk_id"><div class="rank">{{ index+1 }}</div><div><h3>{{ item.filename }}</h3><p>{{ item.snippet }}</p><span>综合 {{ score(item.score) }} · 关键词 {{ score(item.keyword_score) }} · 向量 {{ score(item.vector_score) }}</span></div><small>片段 {{ (item.citation?.chunk_index ?? 0)+1 }}</small></article><p v-if="searched&&!results.length" class="empty">没有检索到相关内容</p></section>
        <section v-else class="graph-view"><div class="graph-stage"><svg viewBox="0 0 900 520" preserveAspectRatio="xMidYMid meet"><line v-for="edge in graphEdges" :key="edge.id" :x1="edge.x1" :y1="edge.y1" :x2="edge.x2" :y2="edge.y2"/><g v-for="node in graphNodes" :key="node.id" :transform="`translate(${node.x},${node.y})`" @click="focus=node.raw"><circle :r="node.document?34:24" :class="{document:node.document,active:focus?.entity_id===node.id}"/><text text-anchor="middle" dy="4">{{ node.label }}</text></g></svg><div v-if="!graphNodes.length" class="empty graph-empty">加入并提取文档后即可生成图谱</div></div><aside class="node-detail"><template v-if="focus"><span>{{ focus.entity_type }}</span><h3>{{ focus.name }}</h3><p>字段：{{ focus.attributes?.field_name || '文档节点' }}</p><p>来源：{{ focus.source_filename || '抽取结果' }}</p><small>{{ focus.source_ids?.join('、') || '来源文档已关联' }}</small></template><p v-else>点击图谱节点查看来源信息</p></aside></section>
      </main>
      <main v-else class="main-empty">选择或创建知识库后开始</main>
    </section>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { getDocuments } from '../../api/workspace'
import { addKnowledgeDocument, createKnowledge, getKnowledge, getKnowledgeDocuments, getKnowledgeGraph, searchKnowledge } from '../../api/enterprise'

const collections=ref([]),documents=ref([]),indexedDocuments=ref([]),selectedId=ref(''),documentId=ref(''),query=ref(''),results=ref([]),searched=ref(false),view=ref('search'),creating=ref(false),graph=ref({entities:[],relations:[]}),focus=ref(null)
const form=reactive({name:'',description:'',retrieval_mode:'hybrid'}),modeNames={hybrid:'混合',keyword:'关键词',vector:'向量'}
const selected=computed(()=>collections.value.find(i=>i.id===selectedId.value)),availableDocuments=computed(()=>{const used=new Set(indexedDocuments.value.map(i=>i.document_id));return documents.value.filter(i=>!used.has(i.id))})
const graphNodes=computed(()=>{const nodes=graph.value.entities||[],center={x:450,y:260};return nodes.slice(0,36).map((raw,index)=>{const document=raw.entity_type==='文档',angle=(Math.PI*2*index)/Math.max(1,nodes.length),radius=document?80:180+(index%2)*70;return{id:raw.entity_id,raw,document,x:center.x+Math.cos(angle)*radius,y:center.y+Math.sin(angle)*radius,label:String(raw.name||'节点').slice(0,8)}})})
const graphEdges=computed(()=>{const points=new Map(graphNodes.value.map(i=>[i.id,i]));return(graph.value.relations||[]).map(raw=>{const a=points.get(raw.source_entity_id),b=points.get(raw.target_entity_id);return a&&b?{id:raw.relation_id,x1:a.x,y1:a.y,x2:b.x,y2:b.y}:null}).filter(Boolean)})
const load=async()=>{const[k,d]=await Promise.all([getKnowledge(),getDocuments({limit:100})]);collections.value=k.items;documents.value=d.items;if(!selectedId.value&&collections.value.length)await choose(collections.value[0].id)}
const choose=async id=>{selectedId.value=id;results.value=[];searched.value=false;focus.value=null;indexedDocuments.value=(await getKnowledgeDocuments(id)).items}
const create=async()=>{if(!form.name)return;const item=await createKnowledge(form);creating.value=false;Object.assign(form,{name:'',description:'',retrieval_mode:'hybrid'});await load();await choose(item.id)}
const addDocument=async()=>{await addKnowledgeDocument(selectedId.value,documentId.value);documentId.value='';await choose(selectedId.value);await load()}
const search=async()=>{if(query.value.length<2)return;const data=await searchKnowledge(selectedId.value,query.value);results.value=data.items;searched.value=true}
const showGraph=async()=>{view.value='graph';graph.value=await getKnowledgeGraph(selectedId.value);focus.value=null}
const score=value=>`${Math.round(Number(value||0)*100)}%`
onMounted(()=>load().catch(e=>alert(e.message)))
</script>

<style scoped>
