s:15px;background:#efe9df;font-size:11px}.library-meta small{margin-left:6px;color:#a88a62}.library-meta i{font-style:normal;color:#aaa;font-size:12px}.view-tabs{display:flex;border-bottom:1px solid #e7e2db}.view-tabs button{border:0;background:none;padding:12px 18px;color:#888;cursor:pointer}.view-tabs button.active{color:#9b6b2a;border-bottom:2px solid #d0a564}.search-box{margin-top:18px;display:flex;gap:8px}.search-box input{flex:1}.search-note{font-size:11px;color:#999;margin:9px 3px 14px}.search-view>article{display:grid;grid-template-columns:34px 1fr auto;gap:12px;padding:15px 3px;border-top:1px solid #ebe6df}.rank{width:28px;height:28px;border-radius:8px;background:#eadcc7;color:#9a6c2f;display:grid;place-items:center;font:12px system-ui}.search-view h3{font-size:14px;margin:0}.search-view p{font-size:12px;line-height:1.65;color:#716b64;margin:6px 0}.search-view span,.search-view article>small{font-size:10px;color:#a78d69}.graph-view{display:grid;grid-template-columns:minmax(0,1fr) 210px;gap:12px;margin-top:15px}.graph-stage{position:relative;min-height:480px;background:radial-gradient(circle at center,#fff,#f4f0e9);border:1px solid #e5dfd6;border-radius:13px;overflow:hidden}.graph-stage svg{width:100%;height:100%;min-height:480px}.graph-stage line{stroke:#d4c7b6;stroke-width:1}.graph-stage circle{fill:#e2c79e;stroke:#fff;stroke-width:3;cursor:pointer}.graph-stage circle.document{fill:#aa7a3c}.graph-stage circle.active{stroke:#67491f;stroke-width:4}.graph-stage text{font-size:9px;fill:#4d4439;pointer-events:none}.node-detail{border:1px solid #e5dfd6;border-radius:13px;padding:16px;background:#faf8f4}.node-detail span{font-size:10px;color:#a27132}.node-detail h3{font-size:17px}.node-detail p,.node-detail small{font-size:11px;line-height:1.6;color:#777}.empty,.main-empty{padding:35px;text-align:center;color:#aaa}.graph-empty{position:absolute;inset:0;display:grid;place-content:center}@media(max-width:850px){.workspace{grid-template-columns:1fr}.workspace>aside{max-height:220px;overflow:auto}.graph-view{grid-template-columns:1fr}.create-bar{grid-template-columns:1fr}.hero,.library-head{align-items:flex-start;flex-direction:column}.add-doc{width:100%}.add-doc select{flex:1}}
</style>
